<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import { ArrowLeft, ArrowRight, Close, Collection, Grid, House, Lock, Menu } from "@element-plus/icons-vue";
import type { StarterCard } from "@/api/types";
import type { ShortcutSnapshot, ShortcutsView } from "@/api/shortcuts";
import type { InformationEntry } from "@/api/information";
import { shortcutFolderPath } from "@/agent/shortcutFolderTree";
import ShortcutsPanel from "./ShortcutsPanel.vue";
import PrivateShortcutTree from "./PrivateShortcutTree.vue";
import InformationLibrary from "./studio/InformationLibrary.vue";
const props = withDefaults(defineProps<{ agentId?: string; sessionId?: string | null; disabled?: boolean; active?: boolean; informationBusy?: boolean }>(), { agentId: "", sessionId: "", disabled: false, active: true, informationBusy: false });
const emit = defineEmits<{ insert: [shortcut: ShortcutSnapshot]; insertInformation: [entry: InformationEntry]; openStarter: [card: StarterCard]; manageStarters: []; close: [] }>();
const { t } = useI18n();
type Section = "root" | "information" | "cards" | "private";
const section = ref<Section>("root"), folderId = ref(""), visitedInformation = ref(false), visitedCards = ref(false), directoryOpen = ref(false);
const privateView = ref<ShortcutsView | null>(null);
const information = ref<{ confirmLeave(): Promise<boolean> } | null>(null), privatePanel = ref<{ confirmLeave(): Promise<boolean> } | null>(null);
let navigationSequence = 0, disposed = false, navigating = false;
const blocked = computed(() => props.disabled || props.informationBusy);
const folders = computed(() => privateView.value?.agent_id === (props.agentId || "") ? privateView.value.folders || [] : []);
const path = computed(() => shortcutFolderPath(folders.value, folderId.value));
const title = computed(() => section.value === "information" ? t("shortcutWorkspace.repositoryFolder") : section.value === "cards" ? t("shortcutWorkspace.cardsFolder") : path.value[path.value.length - 1]?.name || t("shortcutWorkspace.privateRootTitle"));
function receivedView(value: ShortcutsView) { if (!disposed && value.agent_id === (props.agentId || "")) privateView.value = value; }
async function leaveCurrent() {
  if (privatePanel.value && !await privatePanel.value.confirmLeave()) return false;
  return !(section.value === "information" && information.value && !await information.value.confirmLeave());
}
async function navigate(next: Section, nextFolder = "") {
  if (blocked.value || navigating || next === section.value && (next !== "private" || nextFolder === folderId.value)) return;
  if (next === "private" && !folders.value.some(folder => folder.id === nextFolder)) return;
  const ticket = ++navigationSequence, agent = props.agentId, session = props.sessionId; navigating = true;
  try {
    if (!await leaveCurrent()) return;
    if (disposed || ticket !== navigationSequence || agent !== props.agentId || session !== props.sessionId || blocked.value) return;
    if (next === "information") visitedInformation.value = true;
    if (next === "cards") visitedCards.value = true;
    folderId.value = next === "private" ? nextFolder : ""; section.value = next; directoryOpen.value = false;
  } finally { if (ticket === navigationSequence) navigating = false; }
}
function back() { if (section.value === "private" && path.value.length > 1) void navigate("private", path.value[path.value.length - 2].id); else void navigate("root"); }
async function close() {
  if (blocked.value || navigating) return;
  const ticket = ++navigationSequence, agent = props.agentId, session = props.sessionId; navigating = true;
  try { if (!await leaveCurrent()) return; if (!disposed && ticket === navigationSequence && agent === props.agentId && session === props.sessionId && !blocked.value) emit("close"); }
  finally { if (ticket === navigationSequence) navigating = false; }
}
function insertInformation(entry: InformationEntry) { if (!disposed && !navigating && !blocked.value && props.active && section.value === "information" && entry.kind !== "folder") emit("insertInformation", entry); }
function insertShortcut(value: ShortcutSnapshot) { if (!disposed && !navigating && !blocked.value && props.active && ["root", "private", "cards"].includes(section.value)) emit("insert", value); }
watch(() => props.agentId, () => { navigationSequence++; navigating = false; privateView.value = null; section.value = "root"; folderId.value = ""; directoryOpen.value = false; });
watch(folders, value => { if (section.value === "private" && !value.some(folder => folder.id === folderId.value)) { navigationSequence++; navigating = false; section.value = "root"; folderId.value = ""; } });
onBeforeUnmount(() => { disposed = true; navigationSequence++; });
defineExpose({ navigate });
</script>
<template>
  <section class="shortcut-workspace" data-testid="shortcut-workspace" :aria-label="t('shortcuts.title')">
    <header class="workspace-header"><button type="button" class="workspace-directory-toggle" :disabled="blocked" :aria-expanded="directoryOpen" :aria-label="t('shortcutWorkspace.folders')" data-testid="shortcut-directories-toggle" @click="directoryOpen = !directoryOpen"><el-icon><Menu /></el-icon><span>{{ t('shortcutWorkspace.folders') }}</span></button><nav class="workspace-breadcrumb" :aria-label="t('shortcutWorkspace.folderPath')"><button v-if="section !== 'root'" type="button" class="workspace-back" :disabled="blocked" :aria-label="t('shortcutWorkspace.backToFolders')" data-testid="shortcut-folders-back" @click="back"><el-icon><ArrowLeft /></el-icon></button><button type="button" class="workspace-root-label" :class="{ active: section === 'root' }" :disabled="blocked" @click="navigate('root')">{{ t('shortcuts.title') }}</button><template v-if="section === 'private'"><template v-for="(folder, index) in path" :key="folder.id"><el-icon class="crumb-separator"><ArrowRight /></el-icon><button type="button" :class="{ active: index === path.length - 1 }" :disabled="blocked" :title="folder.name" @click="navigate('private', folder.id)">{{ folder.name }}</button></template></template><template v-else-if="section !== 'root'"><el-icon class="crumb-separator"><ArrowRight /></el-icon><strong>{{ title }}</strong></template></nav><button type="button" class="workspace-close" :disabled="blocked" :aria-label="t('shortcuts.closePanel')" @click="close"><el-icon><Close /></el-icon></button></header>
    <div class="workspace-layout"><div v-if="directoryOpen" class="workspace-nav-backdrop" @click="directoryOpen = false" /><aside class="workspace-nav" :class="{ 'mobile-open': directoryOpen }" :aria-label="t('shortcutWorkspace.folders')" @keydown.esc.stop.prevent="directoryOpen = false"><div class="workspace-nav-title">{{ t('shortcutWorkspace.folders') }}</div><div role="tree" :aria-label="t('shortcutWorkspace.folders')"><button type="button" role="treeitem" aria-level="1" :aria-expanded="true" :aria-selected="section === 'root'" class="workspace-tree-folder root" :class="{ selected: section === 'root' }" :disabled="blocked" data-testid="shortcut-tree-root" @click="navigate('root')"><el-icon><House /></el-icon><span>{{ t('shortcuts.title') }}</span></button><div class="workspace-system-folders" role="group"><button type="button" role="treeitem" aria-level="2" :aria-selected="section === 'information'" class="workspace-tree-folder" :class="{ selected: section === 'information' }" :disabled="blocked" data-testid="shortcut-tree-information" @click="navigate('information')"><el-icon><Collection /></el-icon><span>{{ t('shortcutWorkspace.repositoryFolder') }}</span><el-icon class="source-lock"><Lock /></el-icon></button><button type="button" role="treeitem" aria-level="2" :aria-selected="section === 'cards'" class="workspace-tree-folder" :class="{ selected: section === 'cards' }" :disabled="blocked" data-testid="shortcut-tree-cards" @click="navigate('cards')"><el-icon><Grid /></el-icon><span>{{ t('shortcutWorkspace.cardsFolder') }}</span><el-icon class="source-lock"><Lock /></el-icon></button></div><div class="workspace-private-label">{{ t('shortcutWorkspace.agentPrivate') }}</div><PrivateShortcutTree :key="agentId" :folders="folders" :selected="section === 'private' ? folderId : ''" :disabled="blocked" @open="navigate('private', $event)" /></div><p class="workspace-nav-hint">{{ t('shortcutWorkspace.virtualFoldersHint') }}</p></aside>
      <main class="workspace-content">
        <ShortcutsPanel ref="privatePanel" v-show="section === 'root' || section === 'private'" private-only hide-close :agent-id="agentId" :session-id="sessionId" :folder-id="folderId" :active="active && (section === 'root' || section === 'private')" :disabled="blocked" :display-title="title" @view="receivedView" @open-folder="navigate('private', $event)" @insert="insertShortcut" @close="close"><template #root-presets><div v-if="section === 'root'" class="workspace-presets" data-testid="shortcut-folder-root"><div class="preset-heading"><strong>{{ t('shortcutWorkspace.presetSources') }}</strong><small>{{ t('shortcutWorkspace.readOnlySourceLabel') }}</small></div><div class="workspace-preset-grid"><button type="button" class="workspace-preset" :disabled="blocked" data-testid="shortcut-folder-information" @click="navigate('information')"><el-icon class="preset-symbol"><Collection /></el-icon><span><strong>{{ t('shortcutWorkspace.repositoryFolder') }}</strong><small>{{ t('shortcutWorkspace.repositoryHint') }}</small></span><el-icon class="source-lock"><Lock /></el-icon></button><button type="button" class="workspace-preset" :disabled="blocked" data-testid="shortcut-folder-cards" @click="navigate('cards')"><el-icon class="preset-symbol"><Grid /></el-icon><span><strong>{{ t('shortcutWorkspace.cardsFolder') }}</strong><small>{{ t('shortcutWorkspace.cardsHint') }}</small></span><el-icon class="source-lock"><Lock /></el-icon></button></div><div class="workspace-private-heading">{{ t('shortcutWorkspace.agentPrivate') }}</div></div></template></ShortcutsPanel>
        <div v-if="visitedInformation" v-show="section === 'information'" class="workspace-information" data-testid="shortcut-information-folder"><InformationLibrary ref="information" picker :active="active && section === 'information'" :disabled="blocked" @select="insertInformation" /></div>
        <ShortcutsPanel v-if="visitedCards" v-show="section === 'cards'" source-only read-only hide-close :agent-id="agentId" :session-id="sessionId" :active="active && section === 'cards'" :disabled="blocked" :display-title="t('shortcutWorkspace.cardsFolder')" @insert="insertShortcut" />
      </main>
    </div>
  </section>
</template>
<style scoped>
